package com.jay.easygest.outils;import android.content.ContentValues;import android.content.Context;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.jay.easygest.model.AccountModel;import com.jay.easygest.model.CreditModel;import com.jay.easygest.model.InfosModel;import java.util.ArrayList;public class AccessLocalInfo {    public static final String NBRCREDIT = "nbrcredit";    public static final String TOTALCREDIT = "totalcredit";    public static final String TABLE_INFOS = "infos";    private final MySqliteOpenHelper accessBD;    private SQLiteDatabase bd;    public AccessLocalInfo(Context contexte) {        this.accessBD = new MySqliteOpenHelper(contexte,null);    }    public void updateTableInfosWhenCreateOrAddCredit(Integer sommeversee){        InfosModel info = this.getInfo();        bd = accessBD.getWritableDatabase();        try{            ContentValues infos_cv = new ContentValues();            infos_cv.put(NBRCREDIT,info.getNbrcredit()+1);            infos_cv.put(TOTALCREDIT,info.getTotalcredit()+sommeversee);            bd.update(TABLE_INFOS,infos_cv,"appnumber = ?", new String[] {String.valueOf(info.getAppnumber())});        } catch (Exception e) {            throw new RuntimeException(e);        }    }    public void modifierCreditInfos(Integer sommeversee){        InfosModel info = this.getInfo();        bd = accessBD.getWritableDatabase();        try{            ContentValues infos_cv = new ContentValues();            infos_cv.put(TOTALCREDIT,info.getTotalcredit()+sommeversee);            bd.update(TABLE_INFOS,infos_cv,"appnumber = ?", new String[] {String.valueOf(info.getAppnumber())});        } catch (Exception e) {            throw new RuntimeException(e);        }    }    /**     *     * @param credit le credit à annuler     */    public boolean updatTableInfosWhenannullerCredit(CreditModel credit){        InfosModel info = this.getInfo();        bd = accessBD.getWritableDatabase();        boolean success = false;        try{            ContentValues infos_cv = new ContentValues();            infos_cv.put(NBRCREDIT,info.getNbrcredit()-1);            infos_cv.put(TOTALCREDIT,info.getTotalcredit()-credit.getSommecredit());          int rslt = bd.update(TABLE_INFOS,infos_cv,"appnumber = ?", new String[] {String.valueOf(info.getAppnumber())});            if (rslt > 0){                success = true;            }        } catch (Exception e) {            return success ;        }        return success;    }    public void updateAccountInfos(Integer sommeversee){        InfosModel info = this.getInfo();        bd = accessBD.getWritableDatabase();        try{            ContentValues infos_cv = new ContentValues();            infos_cv.put("nbraccount",info.getNbraccount()+1);            infos_cv.put("totalaccount",info.getTotalaccount()+sommeversee);            bd.update(TABLE_INFOS,infos_cv,"appnumber = ?", new String[] {String.valueOf(info.getAppnumber())});        } catch (Exception e) {            throw new RuntimeException(e);        }    }    public void modifierAccountInfos(Integer sommeversee){        InfosModel info = this.getInfo();        bd = accessBD.getWritableDatabase();        try{            ContentValues infos_cv = new ContentValues();            infos_cv.put("totalaccount",info.getTotalaccount()+sommeversee);            bd.update(TABLE_INFOS,infos_cv,"appnumber = ?", new String[] {String.valueOf(info.getAppnumber())});        } catch (Exception e) {            throw new RuntimeException(e);        }    }    public void annullerAccountInfos(AccountModel account){        InfosModel info = this.getInfo();        bd = accessBD.getWritableDatabase();        try{            ContentValues infos_cv = new ContentValues();            infos_cv.put("nbraccount",info.getNbraccount()-1);            infos_cv.put("totalaccount",info.getTotalaccount()-account.getSommeaccount());            bd.update(TABLE_INFOS,infos_cv,"appnumber = ?", new String[] {String.valueOf(info.getAppnumber())});        } catch (Exception e) {            throw new RuntimeException(e);        }    }    public InfosModel getInfo(){        ArrayList<InfosModel> _infos = new ArrayList<>();        InfosModel info;        try {            bd = accessBD.getReadableDatabase();            String req = "select * from infos";            Cursor cursor = bd.rawQuery(req, null);            cursor.moveToFirst();            do {                InfosModel infosModel = new InfosModel(cursor.getInt(0), cursor.getInt(1), cursor.getInt(2), cursor.getInt(3) , cursor.getInt(4));                _infos.add(infosModel);            }            while (cursor.moveToNext());            cursor.close();             info = _infos.get(0);        }catch(Exception e){             info = null;        }        return info;    }}